    public class Collections
    {
        public Collections()
        {
        }
        public static Comparable max(Collection xs)
        {
            Iterator xi = xs.iterator();
            Comparable w = (Comparable)xi.next();
            while(xi.hasNext())
            {
                Comparable x = (Comparable)xi.next();
                if(w.compareTo(x) < 0)
                    w = x;
            }
            return w;
        }
